import React from "react";
import { renderHook, act } from "@testing-library/react-native";
import { type FirebaseAuthTypes } from "@react-native-firebase/auth";
import { Player, FirestoreRiddle } from "../../validation/firestoreSchemas";

// Mock the AuthContext module
jest.mock("../AuthContext");

// Import from the main module
import { AuthProvider, useAuth } from "../AuthContext";

// Import mock helpers directly from the mock file
import {
  __setMockState,
  __resetMockState,
  __getMockFunctions,
} from "../__mocks__/AuthContext";

// Debug logging
console.log("useAuth mock function:", useAuth);
console.log("AuthProvider:", AuthProvider);

// Define test data
const mockFirebaseUser = {
  uid: "testUser123",
  email: "test@example.com",
  displayName: "Test User",
} as FirebaseAuthTypes.User;

const mockPlayer: Player = {
  userId: "testUser123",
  email: "test@example.com",
  username: "TestUser",
  displayName: "Test User",
  avatarUrl: "test.jpg",
  xp: 1000,
  coins: 100,
  registeredAt: Date.now(),
  lastLogin: Date.now(),
  progress: {
    dailyChallengeIndex: 0,
    classicIndex: 1,
    tutorialIndex: 0,
  },
  stats: {
    dailyPuzzlesCompleted: 0,
    bestStreak: 0,
    totalWordsGuessed: 0,
    winRate: 0,
    averageGuesses: 0,
    totalScore: 0,
    highestLevelClassic: 0,
    gamesPlayed: 0,
    wins: 0,
    challengeWins: 0,
    winStreak: 0,
    totalWins: 0,
    totalGuessesInWins: 0,
  },
  lastDailyChallengeCompletedAt: undefined,
  hasPurchasedApp: false,
};

const mockDailyRiddle: FirestoreRiddle = {
  riddleId: "dailyRiddle01",
  dailyIndex: 0,
  text: "I am a daily riddle",
  answer: "DAILY",
  category: "general",
  difficulty: "medium",
};

const mockClassicRiddle: FirestoreRiddle = {
  riddleId: "classicRiddle01",
  classicIndex: 1,
  text: "I am a classic riddle",
  answer: "CLASSIC",
  category: "general",
  difficulty: "easy",
};

const wrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <AuthProvider>{children}</AuthProvider>
);

describe("AuthContext", () => {
  beforeEach(() => {
    jest.clearAllMocks();
    __resetMockState();
  });

  it("initial state when not authenticated", () => {
    const { result } = renderHook(() => useAuth(), { wrapper });

    console.log("Hook result:", result.current);

    // First check if result.current exists
    expect(result.current).toBeDefined();

    expect(result.current.isAuthenticated).toBe(false);
    expect(result.current.playerData).toBeNull();
    expect(result.current.currentRiddle).toBeNull();
    expect(result.current.isLoading).toBe(false);
  });

  describe("Authentication Flow", () => {
    it("handles user login", () => {
      const { result } = renderHook(() => useAuth(), { wrapper });

      // Simulate login by setting mock state
      act(() => {
        __setMockState({
          isAuthenticated: true,
          user: mockFirebaseUser,
          playerData: mockPlayer,
          currentRiddle: mockDailyRiddle,
          isDailyChallengeAvailable: true,
          isLoading: false,
        });
      });

      const { current } = renderHook(() => useAuth(), { wrapper }).result;

      expect(current.isAuthenticated).toBe(true);
      expect(current.playerData).toEqual(mockPlayer);
      expect(current.currentRiddle).toEqual(mockDailyRiddle);
      expect(current.isDailyChallengeAvailable).toBe(true);
      expect(current.isLoading).toBe(false);
    });

    it("handles user logout", async () => {
      // Set initial logged in state
      __setMockState({
        isAuthenticated: true,
        user: mockFirebaseUser,
        playerData: mockPlayer,
        currentRiddle: mockDailyRiddle,
      });

      const { result } = renderHook(() => useAuth(), { wrapper });
      expect(result.current.isAuthenticated).toBe(true);

      // Logout
      await act(async () => {
        await result.current.logout();
      });

      expect(result.current.logout).toHaveBeenCalled();
    });
  });

  describe("Game Mode and Riddle Fetching", () => {
    it("changes game mode", () => {
      __setMockState({
        isAuthenticated: true,
        playerData: mockPlayer,
        currentRiddle: mockDailyRiddle,
      });

      const { result } = renderHook(() => useAuth(), { wrapper });

      act(() => {
        result.current.setGameMode("classic");
      });

      expect(result.current.setGameMode).toHaveBeenCalledWith("classic");
    });

    it("sets current riddle to null if daily challenge is not available", () => {
      __setMockState({
        isAuthenticated: true,
        playerData: {
          ...mockPlayer,
          lastDailyChallengeCompletedAt: new Date().getTime(),
        },
        isDailyChallengeAvailable: false,
        currentRiddle: null,
      });

      const { result } = renderHook(() => useAuth(), { wrapper });

      expect(result.current.isDailyChallengeAvailable).toBe(false);
      expect(result.current.currentRiddle).toBeNull();
    });
  });

  describe("Player Data Updates", () => {
    it("updates player classic index", async () => {
      __setMockState({
        isAuthenticated: true,
        playerData: mockPlayer,
      });

      const { result } = renderHook(() => useAuth(), { wrapper });

      const newClassicIndex = 5;
      await act(async () => {
        await result.current.updatePlayerClassicIndex(newClassicIndex);
      });

      expect(result.current.updatePlayerClassicIndex).toHaveBeenCalledWith(
        newClassicIndex
      );
    });

    it("updates player data", async () => {
      __setMockState({
        isAuthenticated: true,
        playerData: mockPlayer,
      });

      const { result } = renderHook(() => useAuth(), { wrapper });

      const updates: Partial<Player> = {
        coins: 150,
        displayName: "Updated Name",
      };

      await act(async () => {
        await result.current.updatePlayerData(updates);
      });

      expect(result.current.updatePlayerData).toHaveBeenCalledWith(updates);
    });
  });

  it("sets current riddle", () => {
    __setMockState({
      isAuthenticated: true,
      playerData: mockPlayer,
    });

    const { result } = renderHook(() => useAuth(), { wrapper });

    const newRiddle: FirestoreRiddle = {
      ...mockClassicRiddle,
      riddleId: "newRiddle101",
      text: "A brand new riddle",
    };

    act(() => {
      result.current.setCurrentRiddle(newRiddle);
    });

    expect(result.current.setCurrentRiddle).toHaveBeenCalledWith(newRiddle);
  });
});
